    return req.headers.get("x-request-id", str(uuid.uuid4()))


def error_payload(code: str, message: str, rid: str) -> dict:
    return {"code": code, "message": message, "request_id": rid}


def error_response(code: str, message: str, rid: str, status: int) -> JSONResponse:
