from decimal import Decimal

PRICES: dict[str, Decimal] = {
    "widget": Decimal("12.34"),
    "gadget": Decimal("9.99"),
    "sprocket": Decimal("4.50"),
}


def price_for(sku: str) -> Decimal:
    return PRICES[sku]


def total_for(items: list[tuple[str, int]]) -> Decimal:
    total = Decimal("0.00")
    for sku, qty in items:
        total += price_for(sku) * qty
    return total

