import json
from decimal import Decimal
from fastapi import APIRouter, Depends, Header, Request
from fastapi.responses import JSONResponse
from sqlalchemy import select
from sqlalchemy.ext.asyncio import AsyncSession
from app.auth import current_customer
from app.db import get_session
from app.errors import error_response, request_id
from app.idempotency import body_hash, save_response, stored_response
from app.logging_setup import order_log
from app.models import OrderStatus
from app.pagination import clamp_limit
from app.schemas import CreateOrderIn, CreateRefundIn, ListOut, OrderDetailOut, OrderOut, PayIn, format_amount
from app.service import cancel_order, create_order, get_order, list_orders, order_body, pay_order, refund_order
from app import prices

router = APIRouter(prefix="/orders")


def order_out(order) -> dict:
    return order_body(order)


def detail_out(order) -> dict:
    base = order_body(order)
    base["items"] = [{"sku": i.sku, "qty": i.qty} for i in order.items]
    base["refunds"] = [{"id": r.id, "amount": format_amount(Decimal(r.amount)), "items": r.items} for r in order.refunds]
    return base


async def _idem_replay(session: AsyncSession, key: str | None, customer: str, scope: str, body: object, rid: str):
    if not key:
        return error_response("missing_idempotency_key", "Idempotency-Key header required", rid, 422)
    row = await stored_response(session, key, customer)
    wanted = body_hash(body)
    if row is not None:
        if row.scope != scope or row.request_hash != wanted:
            return JSONResponse(status_code=422, content={"code": "key_reuse", "message": "key used with different payload", "request_id": rid})
        return JSONResponse(status_code=row.status_code, content=row.response_body)
    return None


@router.post("", status_code=201)
async def post_orders(body: CreateOrderIn, request: Request, session: AsyncSession = Depends(get_session), customer: str = Depends(current_customer), idempotency_key: str | None = Header(default=None, alias="Idempotency-Key")):
    rid = request_id(request)
    payload = body.model_dump()
    replay = await _idem_replay(session, idempotency_key, customer, "create", payload, rid)
    if replay is not None:
        return replay
    try:
        order = await create_order(session, customer, payload["items"], payload.get("currency", "USD"))
    except KeyError as exc:
        return error_response("unknown_sku", f"unknown sku {exc}", rid, 400)
    resp = order_out(order)
    await save_response(session, idempotency_key or "", customer, "create", body_hash(payload), resp, 201)
    await session.commit()
    order_log(order.id, rid).info("order.created")
    return JSONResponse(status_code=201, content=resp)


@router.get("")
async def get_orders(request: Request, cursor: str | None = None, limit: int = 20, session: AsyncSession = Depends(get_session), customer: str = Depends(current_customer)):
    rid = request_id(request)
    if "offset" in request.query_params:
        return JSONResponse(status_code=410, content={"code": "offset_gone", "message": "use cursor pagination", "request_id": rid})
    lim = clamp_limit(limit)
    page, next_cursor = await list_orders(session, cursor, lim)
    orders = [order_out(o) for o in page if o.customer_id == customer]
    return {"orders": orders, "next_cursor": next_cursor, "limit": lim}


@router.get("/{order_id}")
async def get_one(order_id: str, request: Request, session: AsyncSession = Depends(get_session), customer: str = Depends(current_customer)):
    rid = request_id(request)
    order = await get_order(session, order_id)
    if order is None or order.customer_id != customer:
        return error_response("order_not_found", "order missing", rid, 404)
    return detail_out(order)


@router.post("/{order_id}/pay")
async def pay(order_id: str, body: PayIn, request: Request, session: AsyncSession = Depends(get_session), customer: str = Depends(current_customer), idempotency_key: str | None = Header(default=None, alias="Idempotency-Key")):
    rid = request_id(request)
    replay = await _idem_replay(session, idempotency_key, customer, "pay", body.model_dump(), rid)
    if replay is not None:
        return replay
    order = await get_order(session, order_id)
    if order is None or order.customer_id != customer:
        return error_response("order_not_found", "order missing", rid, 404)
    if order.status != OrderStatus.PENDING_PAYMENT.value:
        return error_response("invalid_state", "order not pending", rid, 409)
    order = await pay_order(session, order)
    resp = order_out(order)
    await save_response(session, idempotency_key or "", customer, "pay", body_hash(body.model_dump()), resp, 200)
    await session.commit()
    order_log(order.id, rid).info("order.paid")
    return JSONResponse(status_code=200, content=resp)


@router.post("/{order_id}/cancel")
async def cancel(order_id: str, request: Request, session: AsyncSession = Depends(get_session), customer: str = Depends(current_customer)):
    rid = request_id(request)
    order = await get_order(session, order_id)
    if order is None or order.customer_id != customer:
        return error_response("order_not_found", "order missing", rid, 404)
    if order.status != OrderStatus.PENDING_PAYMENT.value:
        return error_response("invalid_state", "only pending orders cancel", rid, 409)
    order = await cancel_order(session, order)
    await session.commit()
    order_log(order.id, rid).info("order.cancelled")
    return order_out(order)


@router.post("/{order_id}/refunds")
async def refunds(order_id: str, body: CreateRefundIn, request: Request, session: AsyncSession = Depends(get_session), customer: str = Depends(current_customer), idempotency_key: str | None = Header(default=None, alias="Idempotency-Key")):
    rid = request_id(request)
    replay = await _idem_replay(session, idempotency_key, customer, "refund", body.model_dump(), rid)
    if replay is not None:
        return replay
    order = await get_order(session, order_id)
    if order is None or order.customer_id != customer:
        return error_response("order_not_found", "order missing", rid, 404)
    if order.status not in (OrderStatus.PAID.value, OrderStatus.REFUNDED_PARTIAL.value):
        return error_response("invalid_state", "refunds need a paid order", rid, 409)
    amount = Decimal(body.amount) if body.amount is not None else None
    try:
        refund = await refund_order(session, order, body.items and [i.model_dump() for i in body.items], amount)
    except KeyError as exc:
        return error_response("unknown_sku", f"unknown sku {exc}", rid, 400)
    resp = {"id": refund.id, "amount": format_amount(Decimal(refund.amount)), "items": refund.items}
    await save_response(session, idempotency_key or "", customer, "refund", body_hash(body.model_dump()), resp, 201)
    await session.commit()
    order_log(order.id, rid).info("order.refunded")
    return JSONResponse(status_code=201, content=resp)

