import json
from fastapi import APIRouter, Depends, Header, Request
from fastapi.responses import JSONResponse
from sqlalchemy.ext.asyncio import AsyncSession
from app.db import get_session
from app.errors import request_id
from app.logging_setup import order_log
from app.models import OrderStatus
from app.service import get_order, pay_order
from app.timeutils import utcnow
from app.webhooks import check_nonce, verify_signature

router = APIRouter(prefix="/webhooks")


async def _guard(request: Request, signature: str | None, nonce: str | None, rid: str):
    raw = await request.body()
    if not signature or not verify_signature(raw, signature):
        return None, JSONResponse(status_code=401, content={"code": "bad_signature", "message": "invalid signature", "request_id": rid})
    if nonce is not None and not check_nonce(nonce):
        return None, JSONResponse(status_code=401, content={"code": "bad_nonce", "message": "replayed event", "request_id": rid})
    try:
        event = json.loads(raw.decode() or "{}")
    except json.JSONDecodeError:
        return None, JSONResponse(status_code=400, content={"code": "bad_event", "message": "invalid json", "request_id": rid})
    return event, None


@router.post("/payments")
async def payments(request: Request, session: AsyncSession = Depends(get_session), x_signature: str | None = Header(default=None, alias="X-Signature"), x_nonce: str | None = Header(default=None, alias="X-Nonce")):
    rid = request_id(request)
    event, err = await _guard(request, x_signature, x_nonce, rid)
    if err is not None:
        return err
    order = await get_order(session, str(event.get("order_id", "")))
    if order is None:
        return JSONResponse(status_code=404, content={"code": "order_not_found", "message": "order missing", "request_id": rid})
    if event.get("status") == "paid" and order.status == OrderStatus.PENDING_PAYMENT.value:
        await pay_order(session, order)
        await session.commit()
    order_log(order.id, rid).info("webhook.payment")
    return {"ok": True}


@router.post("/refunds")
async def refunds_hook(request: Request, session: AsyncSession = Depends(get_session), x_signature: str | None = Header(default=None, alias="X-Signature"), x_nonce: str | None = Header(default=None, alias="X-Nonce")):
    rid = request_id(request)
    event, err = await _guard(request, x_signature, x_nonce, rid)
    if err is not None:
        return err
    order_log(str(event.get("order_id", "")), rid).info("webhook.refund")
    return {"ok": True}


@router.post("/chargeback")
async def chargeback(request: Request, session: AsyncSession = Depends(get_session), x_signature: str | None = Header(default=None, alias="X-Signature"), x_nonce: str | None = Header(default=None, alias="X-Nonce")):
    rid = request_id(request)
    event, err = await _guard(request, x_signature, x_nonce, rid)
    if err is not None:
        return err
    order_log(str(event.get("order_id", "")), rid).info("webhook.chargeback")
    return {"ok": True}

