import hashlib
import hmac
import time
from app.config import settings

_seen_nonces: dict[str, float] = {}


def verify_signature(raw_body: bytes, signature: str) -> bool:
    expected = hmac.new(settings.webhook_secret.encode(), raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature or "")


def check_nonce(nonce: str, now: float | None = None) -> bool:
    ts = now if now is not None else time.time()
    if not nonce or nonce in _seen_nonces:
        return False
    _seen_nonces[nonce] = ts
    cutoff = ts - 600
    for k in [k for k, v in _seen_nonces.items() if v < cutoff]:
        del _seen_nonces[k]
    return True

